void initialize_wind_spark(struct Moby *m, int i, void *dir) {
    Spk_k_EC7E8 *d = (Spk_k_EC7E8 *)m->pvars;
    float fwd[4];
    float side[4];
    float up[4];
    float t[4];
    float x, y, z;
    char *p;
    int n;
    qcopy(fwd, dir);
    up[0] = 0.0f;
    up[2] = 1.0f;
    up[1] = 0.0f;
    up[3] = 0.0f;
    FastVecCross(side, fwd, up);
    qcopy(d->pos[i], l14_cuboids[d->i504].v);
    x = -d->f14;
    y = randf_sym(0.0f, d->f18);
    z = randf_sym(0.0f, d->f1C);
    FastVecScale(t, fwd, x);
    p = (char *)d->pos[i];
    FastVecAdd(p, p, t);
    FastVecScale(t, side, y);
    FastVecAdd(p, p, t);
    FastVecScale(t, up, z);
    FastVecAdd(p, p, t);
    d->pos[i][3] = random_float_between(D_L14_00161D08_EC7E8, D_L14_00161D0C_EC7E8);
    d->f440[i] = random_float_between(D_L14_00161D00_EC7E8, D_L14_00161D04_EC7E8) * g_frame_time;
    n = scale_ticks(truncate_float_to_s32(d->f14 * 2.0f / d->f440[i]));
    d->n320[i] = n;
    d->n380[i] = n;
    d->n3E0[i] = 0;
}
