/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l14/gameplay/entities/002df080.c, FUN_L14_002eb568. */
void update_wind_sparks(struct Moby *m) {
    Spk_k_EC9C8 *d = (Spk_k_EC9C8 *)m->pvars;
    float dir[4];
    float clip[4];
    float work[4];
    float ratio;
    float first;
    int in_clip;
    int i;
    int opacity;
    short *shade;
    float *pos;
    dir[0] = FastCos(m->rot.z);
    dir[1] = FastSin(m->rot.z);
    dir[2] = 0.0f;
    qcopy(clip, &g_hero_r.motion.pos);
    clip[2] += 1.0f;
    in_clip = is_point_inside_clip_volume(clip, d->i504);
    i = 0;
    pos = d->pos[0];
    shade = d->n3E0;
    do {
        if (FastDecTimer(&d->n320[i]) != 0) {
            if (in_clip == 0 || i < 24) {
                func_L14_002EC7E8_EC9C8(m, i, dir);
            }
        } else {
            opacity = (wind_spark_max_alpha);
            if (d->n380[i] - (wind_spark_fade_ticks) < d->n320[i]) {
                first = IntToFloat(d->n380[i] - d->n320[i]);
                first = first / IntToFloat((wind_spark_fade_ticks));
            } else {
                first = IntToFloat(d->n320[i]);
                first = first / IntToFloat(d->n380[i] - (wind_spark_fade_ticks));
            }
            {
                int s = truncate_float_to_s32(((float)opacity - 0.0f) * first + 0.0f);
                *shade = s;
                /* FAKEMATCH: storing the shade again is a no-op that reload's cse drops; the
                 * extra uses rank `shade` above `m` for register allocation as in retail. */
                if (s != 0) {
                    *shade = s;
                }
            }
            FastVecScale(work, dir, d->f440[i]);
            FastVecAdd(pos, pos, work);
            if (in_clip != 0 && absolute_float(pos[0] - l14_camera.x) < 8.0f &&
                absolute_float(pos[1] - l14_camera.y) < 8.0f && FastDiffRots(m->rot.z, l14_camera.yaw) > 2.3561945f) {
                if (d->n320[i] > scale_ticks(20)) {
                    d->n320[i] = scale_ticks(20);
                }
            }
        }
        pos += 4;
        shade++;
        i++;
    } while (i < 48);
    AddDrawCallback(func_L14_002ECC70_EC9C8, m);
}
