            draw_world_quad(&q[0], 0, 0);
            draw_world_quad(&q[1], 0, 0);
            q[0].col[0] = q[0].col[1] = q[0].col[2];
            q[1].col[0] = q[1].col[1] = q[1].col[2];
            qcopy(&q[0].v[0], &q[0].v[2]);
            qcopy(&q[0].v[1], &q[0].v[3]);
            qcopy(&q[1].v[0], &q[1].v[2]);
            qcopy(&q[1].v[1], &q[1].v[3]);
