/* Update function of moby Qwark Oltanis: claims the moby when close to oltanis_camera_pos, then a state machine on the
 * byte at +0x20 (state 0 waits until the moby may start, state 1 tracks the hero, state 2 marks the moby done and
 * deletes it, as state 3 does), then the aiming tail on the countdowns at data + 0x194 and 0x198. */
void qwark_oltanis_update(char *m) {
    struct QwarkVars *d = (struct QwarkVars *)((Moby *)m)->pvars;
    attach_big_head_cheat_manipulator_to_matching_moby(m);
    if (((Moby *)m)->visible != 0) {
        if (fast_vec_dist(m + 0x10, oltanis_camera_pos) < 28.0f) {
            set_ground_height_band(m);
            m[0x7F] = 0x16;
        }
    }
    switch (((Moby *)m)->state) {
        case 0: {
            unsigned short id;
            if (oltanis_collected_flags_base_r2.collected[(short)(id = ((Moby *)m)->save_id)] != 0 ||
                (*(int *)(help_stats_base_r + 0xAB75 + (((short)id >> 5) * 4 + (g_current_level_index_m << 8))) >>
                 (id & 0x1F)) &
                    1) {
                DeleteMoby(m);
                return;
            }
            if (d->elevator == -1 || d->clip_volume_b == -1) {
                DeleteMoby(m);
                return;
            }
            d->dialog_name = qwark_oltanis_dialogue_name;
            DialogRequest_Init(m, ((char *)d));
            d->started = 1;
            m[0x20] = 1;
            break;
        }
        case 1:
            if (d->started == 1 && is_point_inside_clip_volume(&g_hero.motion.pos, d->clip_volume) != 0) {
                if ((help_stats_base_r + 0xAA35)[((Moby *)m)->mission + (g_current_level_index_m << 4)] != 0xFF) {
                    char *t;
                    jet_clear_persistent((unsigned char)m[0xB0]);
                    t = oltanis_clip_volumes_r + (d->clip_volume_b << 7);
                    jet_reset_camera(t + 0x30, t + 0x70);
                }
                enable_elevator_alternate_route_r(oltanis_mobys_r + (d->elevator << 8));
                d->unk_0C = 255.0f;
            } else {
                d->unk_0C = 1.7f;
            }
            if (Npc_TryStartDialog(m, ((char *)d)) != 0) {
                begin_dialogue_camera_transition(3.0f, m);
                m[0x20] = 2;
            }
            break;
        case 2:
            if (oltanis_game_mode == 2)
                break;
            m[0x20] = 1;
            if (d->dialog_state != 3 && d->dialog_state != 4)
                break;
            if (d->dialog_state == 4) {
                queue_dialogue_message(0x53E2, -1);
            } else {
                queue_dialogue_message(0x36B3, -1);
            }
            grant_inventory_item(0x20, 1);
            mark_elevator_collected(oltanis_mobys_r + (d->elevator << 8));
            *(int *)(help_stats_base_r + 0xAB75 +
                     (((short)((Moby *)m)->save_id >> 5) * 4 + (g_current_level_index_m << 8))) |=
                1 << (((Moby *)m)->save_id & 0x1F);
            oltanis_moby_killed_bits[(short)((Moby *)m)->save_id >> 5] |= 1 << (((Moby *)m)->save_id & 0x1F);
            memcard_Save(0, -1);
            DeleteMoby(m);
            return;
        case 3:
            DeleteMoby(m);
            return;
    }
    {
        float b[4];
        float sx = 0.02f;
        float sy = 0.3f;
        int doit = 0;
        if (((Moby *)m)->prev_seq == 0) {
            char *g = &g_hero.motion.pos;
            char *a_;
            doit = 1;
            if (vec_distance_xy(m + 0x10, g) < 8.0f &&
                FastDiffRots(((Moby *)m)->rot.z, fast_atan2(*(float *)((a_ = g - 0x80) + 0xD0) - ((Moby *)m)->pos.x,
                                                            *(float *)(a_ + 0xD4) - ((Moby *)m)->pos.y)) < 1.5707964f) {
                if (0.01f < FastVecLength(g + 0x80)) {
                    d->look_timer = scale_ticks(0x78);
                } else {
                    fast_dec_timer(&d->look_timer);
                }
            } else if (d->look_timer != 0) {
                d->look_timer = 0;
                qcopy(&d->look_pos, &g_hero.motion.body_center);
            }
            if (fast_dec_timer(&d->look_retarget) != 0) {
                float y;
                float z;
                float x = random_float_between(180.0f, 300.0f);
                d->look_retarget = truncate_float_to_s32_r(multiply_global_factor(x));
                y = FastAddRots(((Moby *)m)->rot.z, random_float_between(-90.0f, 90.0f) * 0.017453292f);
                z = random_float_between(0.0f, 30.0f) * 0.017453292f;
                BuildSphericalOffset(&d->look_pos, 6.0f, y, z);
                FastVecAdd(&d->look_pos, &d->look_pos, m + 0x10);
            }
            if (d->look_timer != 0) {
                qcopy(b, &g_hero.motion.body_center);
                sx = 0.04f;
                sy = 0.3f;
            } else {
                qcopy(b, &d->look_pos);
            }
        }
        if (doit != 0) {
            float w[4];
            float u[4];
            float f20;
            float f2;
            qcopy(w, m + 0x10);
            w[2] = w[2] + 1.0f;
            FastVecSub(u, b, w);
            f20 = FastSubRots(fast_atan2(u[0], u[1]), ((Moby *)m)->rot.z);
            f2 = -fast_atan2(vector_length_xy(u), u[2]);
            if (f20 > 1.5707964f)
                f20 = 1.5707964f;
            else if (f20 < -1.5707964f)
                f20 = -1.5707964f;
            if (f2 > 0.5235988f)
                f2 = 0.5235988f;
            else if (f2 < -0.5235988f)
                f2 = -0.5235988f;
            d->unk_E4 = f2;
            d->unk_E8 = f20 * 0.6f;
            d->unk_168 = f20 * 0.4f;
        }
        if (gCheats[0] != 0)
            d->height = 2.75f;
        update_joint_animation(m, d->body_manip, 0, sx * g_frame_scale_sq, sy * g_frame_scale_sq);
        update_joint_animation(m, d->head_manip, 1, sx * g_frame_scale_sq, sy * g_frame_scale_sq);
    }
}
